function toDto(payment) {
  if (payment.tag === 'Cash') return { type: 'cash', amount: payment.amount };
  return { type: 'card', cardNumber: payment.cardNumber };
}
function fromDto(dto) {
  if (dto.type === 'cash') return { tag: 'Cash', amount: dto.amount };
  return { tag: 'Card', cardNumber: dto.cardNumber };
}

const original = { tag: 'Cash', amount: 500 };
const dto = toDto(original);
const restored = fromDto(dto);

console.log(dto);
console.log(JSON.stringify(original) === JSON.stringify(restored));

